import pathlib
for base in [pathlib.Path('/workspace/source/incoming'), pathlib.Path('/workspace/results'), pathlib.Path('/workspace/source')]:
 print('==', base)
 if not base.exists():
  print('missing'); continue
 for p in sorted(base.rglob('*')):
  if p.is_file():
   print(p.relative_to(base).as_posix() if base!=pathlib.Path('/workspace/source') else p.relative_to(base).as_posix(), p.stat().st_size)
